package org.jlinalg.cli;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.genetics.GemmaKinship;
import static org.jlinalg.cli.NextflowFiles.*;

/** Complete original-input capture, native screening, original execution and final admission. */
final class GemmaWorkflow {
    static final String ACTION="Required action: read WARNINGS.md, FAILURE.json when present, every QC.jsonl disposition, original output/logs and process/process.stderr. Require COMPLETED.json and successful gemma-tools --verify with the exact producing JAR before downstream use. SKIP3: the exact permitted platform/runtime/install/access prerequisite is unavailable; skip the dependent analysis and supply the named prerequisite through separate authorized setup, or retain the skip. FAIL2: invalid/changed input, process, numerical, capacity, cancellation or finalization failure; no complete result is admitted. Preserve all attempts and correct the named cause using NEW paths. No version, sample reordering, scientific repair, unreported author option or alternate model is inferred. Hashes establish integrity, not authenticity, optimizer convergence or biological accuracy. Cell Ranger remains excluded.";
    private GemmaWorkflow(){ }
    static Path start(Path request,Path home,Path report,Path output)throws IOException{
        GemmaRequest.Spec s=GemmaRequest.read(request.toAbsolutePath().normalize(),true);GemmaRuntime runtime=null;
        if(!s.nativeEngine()){
            if(home==null||report==null)throw new GemmaRuntime.Unavailable("Original GEMMA requires an exact private --home and matching --setup-report; dependent analysis skipped");runtime=new GemmaRuntime(home,report);
        }else require(home==null&&report==null,"Native kinship does not use a private runtime/setup report");
        Path root=output.toAbsolutePath().normalize();require(root.getParent()!=null&&root.getParent().toRealPath().equals(root.getParent()),"Require a new result path with canonical existing parent");
        if(runtime!=null)for(Path protectedRoot:List.of(runtime.home(),runtime.report()))require(!root.startsWith(protectedRoot)&&!protectedRoot.startsWith(root),"Result must be outside runtime/setup report and their ancestors");
        long started=System.nanoTime();Runnable check=()->{if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException("GEMMA computation cancelled");if((System.nanoTime()-started)/1000000>s.wallMillis())throw new IllegalStateException("Cooperative GEMMA native/overall wall capacity exceeded");};
        Pin producer=GemmaBundle.producer();boolean created=false;String stage="CREATE_NEW_CAPTURE";
        try{
            Files.createDirectory(root);created=true;writeJson(root.resolve("INCOMPLETE.json"),Map.of("analysis_admitted",false));writeJson(root.resolve("request.json"),s.document());Files.writeString(root.resolve("WARNINGS.md"),"NO COMPLETE GEMMA RESULT ADMITTED\n\n"+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);Files.createDirectory(root.resolve("inputs"));Files.createDirectory(root.resolve("outputs"));
            stage="CAPTURE_COMPLETE_ORIGINAL_INPUTS";long total=0;var originals=new TreeMap<String,Object>();
            for(var row:s.originals().entrySet()){
                Path original=Path.of(row.getValue());Pin before=pin(original,s.inputBytes(),check);total=Math.addExact(total,before.bytes());require(total<=s.inputBytes(),"Complete original input population exceeds input_bytes");Path copy=root.resolve(row.getKey());Files.copy(original,copy);require(pin(copy,s.inputBytes(),check).equals(before)&&pin(original,s.inputBytes(),check).equals(before),"Original input changed during complete capture");originals.put(row.getKey(),Map.of("original",row.getValue(),"pin",before));
            }
            writeJson(root.resolve("source-inputs.json"),Map.of("files",originals,"complete_original_bytes",total,"source_bytes_unchanged",true));
            stage="NATIVE_COMPLETE_INPUT_AND_QC_ADMISSION";
            try(var prepared=GemmaInputs.read(root,s,check)){
                writeDerived(root,prepared,check);
                if(s.nativeEngine()){
                    stage="NATIVE_KINSHIP";
                    try(var out=Files.newBufferedWriter(root.resolve("outputs/kinship.txt"),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){
                        int n=prepared.data.samples().size();long emitted=0;
                        for(int i=0;i<n;i++){check.run();for(int j=0;j<n;j++){String cell=(j==0?"":"\t")+Double.toString(prepared.screened.value(i,j));emitted=Math.addExact(emitted,cell.length());require(emitted<=s.outputBytes(),"Complete native kinship output exceeds output_bytes");out.write(cell);}out.newLine();emitted++;require(emitted<=s.outputBytes(),"Complete native kinship output exceeds output_bytes");}
                    }
                    writeJson(root.resolve("execution.json"),Map.of("engine","native","edition_contract",s.edition(),"mode",s.mode(),"original_executable_run",false));
                }else{
                    stage="ORIGINAL_UNMODIFIED_GEMMA_EXECUTION";Files.createDirectory(root.resolve("runtime"));
                    copy(runtime.home().resolve("runtime.json"),root.resolve("runtime/marker.json"));copy(runtime.report().resolve("COMPLETED.json"),root.resolve("runtime/setup-completed.json"));copy(runtime.report().resolve("health/COMPLETED.json"),root.resolve("runtime/health-completed.json"));writeJson(root.resolve("runtime/provenance.json"),runtime.provenance());
                    List<String> command=command(root.toString(),runtime.home().toString(),s);writeJson(root.resolve("execution.json"),Map.of("engine","original","edition",s.edition(),"mode",s.mode(),"execution_root",root.toString(),"home",runtime.home().toString(),"command",command,"original_executable_modified",false));runtime.verify();
                    var environment=Map.of("PATH","/usr/bin:/bin","LANG","C","LC_ALL","C","OPENBLAS_NUM_THREADS","1","OMP_NUM_THREADS","1","GOTO_NUM_THREADS","1","MKL_NUM_THREADS","1");
                    try{NextflowProcess.executeSession(command,environment,root.resolve("process"),root,root,s.process(),runtime::verify,check);}catch(IOException e){throw new IOException("Original GEMMA execution failed or exceeded a declared process/resource limit. Inspect retained process/process.json, process/process.stderr and original outputs; no complete result is admitted",e);}runtime.verify();
                }
            }
            stage="COMPLETE_OUTPUT_CONSISTENCY";var audit=GemmaBundle.audit(root,s,false,check);writeJson(root.resolve("OUTPUT-AUDIT.json"),audit);Files.writeString(root.resolve("WARNINGS.md"),warnings(s),StandardCharsets.UTF_8,StandardOpenOption.TRUNCATE_EXISTING);checkOriginals(s,originals,check);if(runtime!=null)runtime.verify();require(producer.equals(GemmaBundle.producer()),"Producing executable changed during analysis");
            stage="FINALIZE_CAPTURED_RESULT";var files=GemmaBundle.files(root,s,check);files.remove("INCOMPLETE.json");writeJson(root.resolve("manifest.json"),Map.of("schema_version",1,"profile","gemma-captured-plink-univariate-v1","files",files,"producer",producer,"analysis_admitted",true,"whole_paper_reproduced",false,"optimizer_convergence_certified",false));writeJson(root.resolve("COMPLETED.json"),Map.of("schema_version",1,"status","COMPLETE_GEMMA_CAPTURED_CONTRACT","manifest",pin(root.resolve("manifest.json"),16777216,check),"analysis_admitted",true));GemmaBundle.verify(root,true,check);checkOriginals(s,originals,check);if(runtime!=null)runtime.verify();check.run();Files.delete(root.resolve("INCOMPLETE.json"));return root;
        }catch(IOException|RuntimeException|Error failure){if(created)failure(root,stage,failure);throw failure;}
    }
    static List<String> command(String root,String home,GemmaRequest.Spec s){
        // Execution is Linux-only; retain its exact POSIX strings in portable readback.
        String p=root+"/inputs/";var args=new ArrayList<String>(List.of(home+"/bin/gemma-"+s.edition(),"-bfile",p+"data","-p",p+"phenotype.txt","-n","1","-maf",Double.toString(s.numeric().minimumFrequency()),"-miss",Double.toString(s.numeric().maximumMissingness()),"-hwe",Double.toString(s.numeric().minimumHwe()),"-r2",Double.toString(s.numeric().maximumCovariateFraction())));
        if(s.originals().containsKey("inputs/covariates.txt"))args.addAll(List.of("-c",p+"covariates.txt"));
        if(s.association())args.addAll(List.of("-k",p+"kinship.txt","-lmm",s.mode().substring(3),"-lmin","1.0E-5","-lmax","100000.0","-region","10"));else args.addAll(List.of("-gk",s.mode().substring(2)));
        args.addAll(List.of("-outdir",root+"/outputs","-o","result"));return List.copyOf(args);
    }
    static void writeDerived(Path root,GemmaInputs input,Runnable check)throws IOException{
        try(var out=Files.newBufferedWriter(root.resolve("QC.jsonl"),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){for(var row:input.screened.predictors()){check.run();out.write(NextflowJson.json(predictor(row)));out.write('\n');}}
        Files.writeString(root.resolve("samples.tsv"),samples(input),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
    }
    static Map<String,Object> predictor(GemmaKinship.Predictor p){
        var row=new LinkedHashMap<String,Object>();row.put("id",p.id());row.put("source_ordinal",p.sourceOrdinal());row.put("qc_called",p.qcCalled());row.put("qc_missing",p.qcMissing());row.put("qc_allele1_frequency",nullable(p.qcAllele1Frequency()));row.put("hwe_p",nullable(p.hweP()));row.put("covariate_fraction",nullable(p.covariateFraction()));row.put("all_called",p.allCalled());row.put("all_mean",nullable(p.allMean()));row.put("all_imputed_variance",nullable(p.allImputedVariance()));row.put("status",p.status().toString());return row;
    }
    private static Double nullable(double value){return Double.isFinite(value)?value:null;}
    static String samples(GemmaInputs input){var out=new StringBuilder("FID\tIID\tQC_COMPLETE_CASE\n");for(int i=0;i<input.mask.length;i++){var row=input.data.samples().get(i);out.append(row.familyId()).append('\t').append(row.individualId()).append('\t').append(input.mask[i]?"1":"0").append('\n');}return out.toString();}
    static String warnings(GemmaRequest.Spec s){return "GEMMA WARNINGS AND REQUIRED ACTION\n\nEngine "+s.engine()+", explicit edition contract "+s.edition()+", mode "+s.mode()+", declared genome build "+s.build()+".\n\nQC uses phenotype/covariate complete cases; kinship construction uses ALL FAM rows. Missing hard calls use separate means in those populations. Standardized kinship uses observed variance after mean imputation, not2p(1-p), without trace normalization. A1 frequency can exceed0.5; exported original frequencies have only3 decimals. Every selected BIM row and every FAM sample remains visible in QC.jsonl and samples.tsv. Sample sidecars declare positional identity; they cannot establish that the supplied phenotype or external matrix was generated correctly.\n\nInput admission requires a unit first intercept, no redundant/constant additional design column, resolved distinct alleles, diploid hard calls, unique identifiers, one explicit phenotype and finite decimal numbers or literal NA in phenotype/covariates. Excluded phenotype/covariate rows remain captured. Numeric -9 in an explicit phenotype file is a numeric value under the original source contract. BIM/FAM metadata is bounded to64MiB total; text lines to1MiB; covariates to64 columns. Numerical/work/byte bounds are admission estimates, not guarantees of available JVM heap. Native/overall time checks are cooperative.\n\nA supplied kinship is checked in exact FAM order, for symmetry and positive semidefiniteness within text-rounding tolerance1e-6*N*max(1,maxAbsEntry). That tolerance is used for validation only; the source matrix is passed unchanged. SNP QC uses an independent orthogonal projection; any disagreement with original output populations rejects the entire capture. Boundary lambda estimates may occur under the explicitly selected original optimizer limits1e-5..1e5 with10 regions. A successful finite output does not certify optimizer convergence. Review all original warnings and boundary counts in OUTPUT-AUDIT.json. The original near-zero-eigenvalue warning is retained; unexpected numerical/error diagnostics reject admission.\n\nNative kinship executes Java only. Original association fitting and optional original kinship require the separately qualified unmodified Linux x86_64 releases0.98.1/0.98.3/0.98.5. Setup is separate and analysis never downloads, installs, repairs or reseals. No PanGEMMA substitution, LOCO, multivariate LMM, BSLMM, phenotype BLUP estimation, imputation, LD pruning or full paper reproduction is claimed. P176's literal0.983 remains unresolved; P248 supplies precomputed BLUP phenotypes rather than reporting GEMMA-BSLMM training.\n\nPortable verification checks complete captured files, sample/QC/output consistency and exact producer identity. It does not rerun the original runtime, refit the association model or consult original host paths. Retain the exact producer JAR, source audit, setup evidence and runtime privately.\n\n"+ACTION+"\n";}
    static void failure(Path root,String stage,Throwable e){try{Files.deleteIfExists(root.resolve("COMPLETED.json"));if(!Files.exists(root.resolve("INCOMPLETE.json")))writeJson(root.resolve("INCOMPLETE.json"),Map.of("analysis_admitted",false));writeJson(root.resolve("FAILURE.json"),Map.of("status",e instanceof GemmaRuntime.Unavailable?"SKIP3_DEPENDENT_ANALYSIS_SKIPPED":"FAIL2_NO_COMPLETE_RESULT","stage",stage,"error",e.toString(),"required_action",ACTION));Files.writeString(root.resolve("WARNINGS.md"),"NO COMPLETE GEMMA RESULT ADMITTED\n\n"+stage+": "+e+"\n\n"+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}catch(IOException diagnostic){e.addSuppressed(diagnostic);}}
    private static void checkOriginals(GemmaRequest.Spec s,Map<String,Object> originals,Runnable check)throws IOException{for(var e:s.originals().entrySet())require(pin(Path.of(e.getValue()),s.inputBytes(),check).equals(object(originals.get(e.getKey())).get("pin")),"Original input changed before final admission");}
    private static void copy(Path src,Path target)throws IOException{Pin before=pin(src,1048576,()->{});Files.copy(src,target);require(before.equals(pin(target,1048576,()->{}))&&before.equals(pin(src,1048576,()->{})),"Runtime evidence changed during capture");}
    private static void require(boolean yes,String message)throws IOException{if(!yes)throw new IOException(message);}
}
